describe('Record Date Display', () => {
    beforeEach(() => {
        cy.visit('/records'); // Adjust the URL to your application's records page
    });

    it('should display the created date and last modified date for a record', () => {
        cy.get('.record').first().within(() => {
            cy.get('.created-date').should('be.visible').and('not.be.empty');
            cy.get('.last-modified-date').should('be.visible').and('not.be.empty');
        });
    });

    it('should handle the case when dates are not available', () => {
        cy.get('.record').first().within(() => {
            cy.get('.created-date').should('have.text', 'N/A');
            cy.get('.last-modified-date').should('have.text', 'N/A');
        });
    });
});
